Translate("esES", "prospector-ryedol", {
	title = "Prospector Ryedol",
	subtitle = "Prospector de la Liga de Expedicionarios",
	found = [=[El campamento de la Liga al sur de la Excavación de Piemartillo]=],
	hint = [=[Encuentre al prospector que sobrevivió a la caída de la excavación de Hammertoe.]=],
	allegiance = "Liga de Expedicionarios",
	aliases = { "Ryedol" },
	sections = {
		{
			title = "Resumen",
			text = [=[El prospector Ryedol trabajaba a las órdenes del explorador Hammertoe Grez en su excavación del norte de las {link:badlands}Tierras Inhóspitas{/link}. Cuando atacó el clan Shadowforge, fue uno de los pocos que escaparon. Ahora mantiene un pequeño campamento al sur del lugar arruinado con {link:sigrun-ironhew}Sigrun Ironhew{/link} y los demás supervivientes. Habla sin rodeos y está cansado, y dice que cada día en las Tierras Inhóspitas es un mal día.]=],
		},
		{
			title = "Importancia",
			text = [=[Ryedol es el hilo que une el destino de Hammertoe con {link:ironforge}Forjaz{/link}. Por él supo el reino que los Shadowforge no se limitaban a saquear. Buscaban secretos de los titanes, y el saber que Hammertoe llevaba en la cabeza.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Escapó del ataque de los Shadowforge contra la excavación de Hammertoe.
• Supo por un mapa garabateado que Hammertoe había sido llevado vivo a {link:uldaman}Uldaman{/link}.
• Envió a un buscador a la cámara para encontrar a su antiguo maestro.
• Hizo llegar el amuleto de Hammertoe al historiador {link:historian-karnik}Karnik{/link}, en {link:ironforge}Forjaz{/link}, por mano de otro.]=],
		},
		{
			title = "Sin registro",
			text = [=[Nada se ha escrito de la vida de Ryedol antes de las {link:badlands}Tierras Inhóspitas{/link}.]=],
		},
	},
	chapters = {
		{
			title = "El pico de la suerte",
			hint = "Recupere de los Shadowforge el pico del prospector.",
			text = [=[Ryedol lo perdió todo en el ataque, incluso su pico de la suerte. Creía que se lo había llevado uno de los Shadowforge. Cuando se lo devolvieron, lo agradeció. También se sintió inquieto. Los {link:dark-iron-dwarves}Hierro Negro{/link} no habían atacado la excavación al azar, dijo. Buscaban algo.]=],
		},
		{
			title = "Una señal de esperanza",
			hint = [=[Cuente al prospector lo que revela el mapa garabateado con tiza.]=],
			text = [=[Cerca de la excavación arruinada se encontró un mapa con un mensaje garabateado con tiza: se llevaban a Hammertoe a {link:uldaman}Uldaman{/link}. Ryedol lo había llorado por muerto. Ahora entendió por qué los Shadowforge lo habían perdonado. Querían lo que Hammertoe sabía de las excavaciones de los titanes. Los {link:dark-iron-dwarves}Hierro Negro{/link} llevaban mucho tiempo buscando la manera de construir gólems más fuertes. Hammertoe había estudiado esos mismos secretos para detenerlos.]=],
		},
		{
			title = "La perspectiva de la fe",
			hint = "Lleve al prospector lo que dejó Hammertoe.",
			text = [=[Encontraron a Hammertoe en {link:uldaman}Uldaman{/link}, pero se estaba muriendo. Devolvió su amuleto, la obra de su vida, y pidió que fuera para Ryedol. Ryedol dijo que había sido más feliz cuando creía muerto a su maestro. Luego se sobrepuso. Hammertoe había trabajado con el historiador {link:historian-karnik}Karnik{/link} de {link:ironforge}Forjaz{/link}, y Karnik sabría lo que significaba el amuleto. Ryedol se lo hizo llegar, para que aquella muerte no fuera en vano.]=],
		},
	},
	mentions = {
		{ text = "Un {link:dwarves}enano{/link} y sus herramientas" },
		{ text = "Una señal de esperanza" },
		{
			text = [=[Una señal de esperanza, enviado a {link:uldaman}Uldaman{/link}]=],
		},
		{ text = "La perspectiva de la fe, el amuleto de Hammertoe devuelto" },
		{
			text = [=[La perspectiva de la fe, llevado a {link:ironforge}Forjaz{/link}]=],
		},
	},
	bonds = {
		{ id = "hammertoe-grez", name = "Hammertoe Grez", note = "su maestro" },
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "comparte su campamento" },
		{ id = "historian-karnik", name = "Historiador Karnik", note = "el compañero de Hammertoe en Forjaz" },
	},
})

