			title = "Resumen",
			text = [=[{link:garek-bandarion}Garek{/link} es un mago enviado a las {link:badlands}Tierras Inhóspitas{/link} por un maestro del {link:kirin-tor}Kirin Tor{/link}, Krasus. El mago mantiene un campamento solitario cerca del {link:lethlor-ravine}Barranco Lethlor{/link} y dice poco de su encargo, solo que es de gran importancia y que tiene que ver con los problemas que se gestan en el barranco.]=],
		},
