			title = "Importancia",
			text = [=[{link:garek-bandarion}Garek{/link} demuestra que el {link:kirin-tor}Kirin Tor{/link} aún vigila al Vuelo Negro, incluso en estos años turbulentos. Bajo el {link:lethlor-ravine}Barranco Lethlor{/link} yacen dos lugartenientes de {link:deathwing}Alamuerte{/link}, y su maestro ha decidido que no puede permitirse ningún riesgo de que queden libres.]=],
		},
