Translate("esES", "lotwil-veriatus", {
	title = "Lotwil Veriatus",
	subtitle = "Mago y manitas de Kharanos",
	found = "Su campamento en Terraseca",
	hint = [=[Encuentre al mago gnomo que prueba sus inventos en Terraseca.]=],
	allegiance = "Gnomos · Kharanos",
	aliases = { "Lotwil" },
	sections = {
		{
			title = "Resumen",
			text = [=[Lotwil Veriatus es un {link:gnomes}gnomo{/link} que mezcla alquimia, ingeniería y magia arcana al servicio de su propia curiosidad. Ha venido de {link:kharanos}Kharanos{/link} a las {link:badlands}Tierras Inhóspitas{/link} para construir su mayor obra: unos grilletes de atadura elemental, que permitirían a un mago dominar elementales mucho más fuertes que cualquiera de los invocados hasta ahora. Su ayudante {link:lucien-tosselwrench}Lucien{/link} y su torpe sirviente mecánico, Servo, comparten su campamento. Lotwil es brillante, despistado y está alegremente convencido de que cada contratiempo es pequeño.]=],
		},
		{
			title = "Importancia",
			text = [=[Lotwil es un erudito de verdadero renombre en las ciencias elementales, y hasta la {link:horde}Horda{/link} de {link:kargath}Kargath{/link} busca su juicio. También tiene un pasado. Hace mucho luchó contra un {link:dark-iron-dwarves}Hierro Negro{/link} que convirtió la obra de su vida en armas, y creía muerto a ese enemigo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudia los elementales de roca de las {link:badlands}Tierras Inhóspitas{/link} para construir sus grilletes.
• Enfría y refuerza sus grilletes con aceite de escarcha y un artefacto llamado girocronátomo.
• Invoca a un guardián de piedra con sus grilletes terminados, lo que no sale como había planeado.
• Conoce las marcas del creador de gólems Argelmach.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las crónicas no cuentan cómo se conocieron Lotwil y Argelmach, ni cómo llegó el {link:dark-iron-dwarves}Hierro Negro{/link} a hacerse con la obra del {link:gnomes}gnomo{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Estudio de los elementos",
			hint = [=[Reúna lo que el gnomo necesita de los elementales de roca de las Tierras Inhóspitas.]=],
			text = [=[Fragmentos de los elementales menores, losas de los mayores y, por último, los brazales de atadura de roca del más grande de ellos. Cada pieza permitió a Lotwil probar sus hechizos contra la materia de la roca viva. Cada prueba salió como había predicho. Empezó a hablar de los elementales que pronto dominaría, y de cómo dejarían en ridículo todas las invocaciones anteriores.]=],
		},
		{
			title = "Esto va a ser difícil",
			hint = [=[Ayude al gnomo a terminar sus grilletes, y ocúpese de lo que venga después.]=],
			text = [=[Los grilletes estaban terminados. Lotwil llamó a {link:lucien-tosselwrench}Lucien{/link} y a Servo como testigos, e invocó a un guardián de piedra elemental. No obedeció. Cuando la criatura fue vencida y sus grilletes recuperados, Lotwil admitió que no había sido el resultado que esperaba. No supo decir qué había fallado. Se alegraba, dijo, de que su magia hubiera estado allí para enviar a la criatura a su hogar.]=],
		},
		{
			title = "El alzamiento de las máquinas",
			hint = [=[Lleve el fragmento elemental marcado desde Kargath hasta el campamento del gnomo.]=],
			text = [=[Los fragmentos procedían de gólems de {link:burning-steppes}Las Estepas Ardientes{/link}, y llevaban unas iniciales. Cuando Lotwil las vio, palideció. Conocía las marcas. Pertenecían a Argelmach, un {link:dark-iron-dwarves}Hierro Negro{/link} que había torcido la propia obra de Lotwil hacia fines malvados, y al que Lotwil había matado con su propia mano años atrás. Cuando sacaron la cabeza de Argelmach de las {red:blackrock-depths}Profundidades de Roca Negra{/red}, no era de carne. Era una máquina hecha a imagen de Argelmach, y Lotwil temía que otra se alzara para ocupar su lugar.]=],
		},
	},
	mentions = {
		{ text = "Estudio de los elementos: roca" },
		{ text = "Estudio de los elementos: roca" },
		{ text = "Estudio de los elementos: roca" },
		{ text = "Cabeza fría" },
		{ text = "Giro... ¿qué?" },
		{ text = "Esto va a ser difícil" },
		{ text = "Esto va a ser difícil, el engranaje entregado" },
		{ text = "Esto va a ser difícil, el guardián desatado" },
		{
			text = [=[El alzamiento de las máquinas, el fragmento traído de {link:kargath}Kargath{/link}]=],
		},
		{ text = "El alzamiento de las máquinas, la cabeza de Argelmach" },
	},
	bonds = {
		{ id = "lucien-tosselwrench", name = "Lucien Tosselwrench", note = "su ayudante" },
		{ id = "hierophant-theodora-mulvadania", name = "Hierofante Theodora Mulvadania", note = "busca su juicio" },
		{ id = "golem-lord-argelmach", name = "Señor de los gólems Argelmach", note = "su viejo enemigo" },
	},
})

