	sections = {
		{
			title = "Resumen",
			text = [=[Rigglefuzz es un goblin que vive en el corazón de las {link:badlands}Tierras Inhóspitas{/link}, donde sobrevive a base de astucia. Mantiene alejadas a las bestias con bombas de destello, y está orgulloso de sus alas de buitre a la brasa, cuyo olor, asegura, atrae a los hambrientos desde kilómetros de distancia. También guarda un rencor. Los Shadowforge se lo llevaron una vez a la {link:angor-fortress}Fortaleza de Angor{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Rigglefuzz es quien enseñó a los Shadowforge el secreto de las extrañas piedras de {link:uldaman}Uldaman{/link}. Lo llevaron a la {link:angor-fortress}Fortaleza de Angor{/link} para estudiar dos clases de piedra de la cámara, y descubrió que, bien tratadas, eran fuentes de poder estables y duraderas. Cuando se lo dijo, lo echaron y empezaron a excavar en busca de más.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fabrica bombas de destello con perlas azules trituradas traídas de los arrecifes de la {link:stranglethorn-vale}Vega de Tuercespina{/link}.
• Cocina alas de buitre y comparte la receta con quienes lo ayudan.
• Quiere las piedras de poder de {link:uldaman}Uldaman{/link} para sus propios artefactos.]=],
		},
	},
	mentions = {
		{ text = "Alas de buitre a la brasa" },
		{ text = "Buceo de perlas" },
		{ text = "Receta de bomba de destello" },
		{ text = "Piedras de poder" },
	},
	bonds = {
		{ id = "martek-the-exiled", name = "Martek el Exiliado", note = "comparte su campamento" },
	},
})

Translate("esES", "martek-the-exiled", {
	title = "Martek el Exiliado",
	subtitle = "Herrero exiliado",
	found = "El campamento del Valle de los Colmillos",
	hint = [=[Encuentre al herrero que ha venido a las Tierras Inhóspitas para que lo dejen en paz.]=],
	allegiance = "Ninguna",
	aliases = { "Martek" },
	sections = {
		{
			title = "Resumen",
			text = [=[Martek es un herrero de gran destreza que sabe del metal más que casi nadie. También es un hombre perseguido. Muchos lo querrían muerto, y espera que cada extraño sea uno de ellos. Pregunta a los visitantes si vienen por el hacha que hizo para {link:gath-ilzogg}Gath'Ilzogg{/link}, o a vengar el honor de una tal duquesa Pamay, y dice que le da igual cuál de las dos cosas.]=],
		},
		{
			title = "Importancia",
			text = [=[Martek encontró en las {link:badlands}Tierras Inhóspitas{/link} un metal llamado indurio, que resiste el calor y la tensión como ningún otro. El verdadero mineral yace en lo hondo de {link:uldaman}Uldaman{/link}. Por él, la noticia llegó al {link:gnomes}gnomo{/link} {link:fizzle-brassbolts}Fizzle Brassbolts{/link} en {link:thousand-needles}Las Mil Agujas{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Forjó un hacha para el {link:ogres}ogro{/link} {link:gath-ilzogg}Gath'Ilzogg{/link}.
• Prueba las escamas de indurio que llevan los troggs Stonevault.
• Avisa a {link:fizzle-brassbolts}Fizzle Brassbolts{/link} de que el indurio puede servir para hacer pistones para su bólido.]=],
		},
	},
	mentions = {
		{ text = "Martek el Exiliado" },
		{ text = "Indurio" },
		{ text = "Noticias para Fizzle" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "uno de los pocos que le desean el bien" },
		{ id = "rigglefuzz", name = "Rigglefuzz", note = "comparte su campamento" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "compró su hacha" },
	},
})

Translate("esES", "warlord-goretooth", {
	title = "Señor de la guerra Goretooth",
	subtitle = "Comandante de la Fuerza Expedicionaria de Kargath",
	found = "Kargath",
	hint = [=[Hable con el señor de la guerra que dirige el ejército de la Horda en Kargath.]=],
	allegiance = "Horda · Fuerza Expedicionaria de Kargath",
	aliases = { "Goretooth" },
	sections = {
		{
			title = "Resumen",
			text = [=[El señor de la guerra Goretooth dirige la Fuerza Expedicionaria de {link:kargath}Kargath{/link}, el ejército que la {link:horde}Horda{/link} mantiene en las {link:badlands}Tierras Inhóspitas{/link} para combatir al {link:blackrock-clan}clan Roca Negra{/link} y a los {link:dark-iron-dwarves}Hierro Negro{/link} de la {link:blackrock-mountain}Montaña Roca Negra{/link}. Es un soldado duro, demasiado ocupado para las visitas y demasiado orgulloso para mostrar miedo. Habla con órdenes. Sus carteles de búsqueda cuelgan por todo Kargath, y cada uno promete un tributo a quien cumpla su sentencia.]=],
		},
		{
			title = "Importancia",
			text = [=[Goretooth dirige la campaña más larga de la {link:horde}Horda{/link} en los {link:eastern-kingdoms}Reinos del Este{/link}. Su fuerza ha sufrido mucho: el general {link:dark-iron-dwarves}Hierro Negro{/link} Angerforge masacró su división 109. Goretooth ha jurado que Angerforge lo pagará.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Dirige la F.E.K. desde {link:kargath}Kargath{/link}, con sus oficiales {link:lexlort}Lexlort{/link}, {link:galamav-the-marksman}Galamav{/link}, {link:shadowmage-vivian-lagrave}Vivian Lagrave{/link} y {link:hierophant-theodora-mulvadania}Theodora Mulvadania{/link}.
• Publica órdenes de matar a los soldados Anvilrage del general Angerforge en las {red:blackrock-depths}Profundidades de Roca Negra{/red}.
• Planea la operación que llevará ante la justicia al Carnicero de {link:blackrock-mountain}Roca Negra{/link}.
• Ordena la muerte de los amos de la {red:blackrock-spire}Cumbre de Roca Negra{/red}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Nada se ha escrito del clan de Goretooth ni de sus hazañas antes de la F.E.K.]=],
		},
	},
	chapters = {
		{
			title = "Matar nada más verlos",
			hint = [=[Responda a los carteles del señor de la guerra contra los Hierro Negro.]=],
			text = [=[Los carteles aparecieron en los muros de {link:kargath}Kargath{/link} en nombre del señor de la guerra. Los hombres de Angerforge eran asesinos despiadados, responsables de la matanza de la 109. Había que destruir a todo guardia, celador y oficial Anvilrage de las Profundidades. Goretooth prometió tributos, y a Angerforge le prometió algo peor.]=],
		},
		{
			title = "Muerte a Angerforge",
			hint = [=[Termine la operación del señor de la guerra contra el general Hierro Negro.]=],
			text = [=[La última operación era la que el señor de la guerra había estado esperando. El general Angerforge, el Carnicero de {link:blackrock-mountain}Roca Negra{/link}, cayó muerto en las Profundidades. Goretooth lo llamó justicia al fin, y entregó un medallón de la F.E.K. a quien lo había llevado a cabo.]=],
		},
		{
			title = "La orden del señor de la guerra",
			hint = [=[Cumpla la orden del señor de la guerra en la Cumbre de Roca Negra.]=],
			text = [=[Goretooth ordenó la muerte de tres amos de la Cumbre de {link:blackrock-mountain}Roca Negra{/link}, y pidió todos los documentos que se hallaran entre sus pertenencias. Los documentos le llegaron. Cuando los leyó, su piel verde palideció por un instante. Decían que Rend Blackhand vivía, un cacique al que se creía muerto hacía mucho. Goretooth envió aviso a {link:eitrigg}Eitrigg{/link} y a {link:thrall}Thrall{/link}, en {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[MATAR NADA MÁS VERLOS: enanos {link:dark-iron-dwarves}Hierro Negro{/link}]=],
		},
		{
			text = [=[MATAR NADA MÁS VERLOS: altos oficiales {link:dark-iron-dwarves}Hierro Negro{/link}]=],
		},
		{ text = "Operación: muerte a Angerforge" },
		{ text = "La orden del señor de la guerra" },
		{ text = "La sabiduría de {link:eitrigg}Eitrigg{/link}" },
	},
	bonds = {
		{ id = "lexlort", name = "Lexlort", note = "su jefe de reconocimiento" },
		{ id = "galamav-the-marksman", name = "Galamav el Tirador", note = "uno de sus oficiales" },
		{ id = "eitrigg", name = "Eitrigg", note = "quien mejor conoce a los Roca Negra" },
		{ id = "thrall", name = "Thrall", note = "su Jefe de Guerra" },
	},
})

Translate("esES", "lexlort", {
	title = "Lexlort",
	subtitle = "Gran maestro de reconocimiento de la F.E.K.",
	found = "Kargath",
	hint = [=[Hable con el maestro de exploradores de la Fuerza Expedicionaria de Kargath.]=],
	allegiance = "Horda · Fuerza Expedicionaria de Kargath",
	sections = {
		{
			title = "Resumen",
			text = [=[El gran maestro Lexlort dirige el reconocimiento de la Fuerza Expedicionaria de {link:kargath}Kargath{/link}. Fue él quien descubrió dónde adiestran a sus soldados los altos oficiales de los {link:dark-iron-dwarves}Hierro Negro{/link}. Siguió el rastro del traidor {link:grark-lorkrub}Grark Lorkrub{/link} a través de {link:searing-gorge}La Garganta de Fuego{/link}, por dentro de la montaña y hasta {link:burning-steppes}Las Estepas Ardientes{/link}, donde los {link:blackrock-clan}orcos Roca Negra{/link} le dieron refugio.]=],
