		},
		{
			title = "Hazañas",
			text = [=[• Trae de vuelta a {link:grark-lorkrub}Grark Lorkrub{/link} con grilletes de torio para que responda por su traición.
• Envía a un buscador tras Bijou, una agente goblin que aceptó el dinero de la F.E.K. y también el de un segundo amo.
• Recibe el informe de Bijou sobre los {link:blackrock-clan}orcos Roca Negra{/link}, y admite que se le ha vuelto a escurrir.]=],
		},
	},
	mentions = {
		{ text = "{link:grark-lorkrub}Grark Lorkrub{/link}" },
		{ text = "Situación precaria" },
		{ text = "La agente Bijou" },
		{ text = "El informe de reconocimiento de Bijou" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Señor de la guerra Goretooth", note = "su comandante" },
		{ id = "grark-lorkrub", name = "Grark Lorkrub", note = "el traidor al que persiguió" },
	},
})

Translate("esES", "galamav-the-marksman", {
