• Ordena la muerte de Halycon, la gran madre de la guarida de los huargos {link:blackrock-mountain}Roca Negra{/link}.]=],
		},
	},
	mentions = {
		{ text = "Comandante Gor'shak" },
		{ text = "La señora de la manada" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Señor de la guerra Goretooth", note = "su comandante" },
		{ id = "commander-gor-shak", name = "Comandante Gor'shak", note = "un prisionero de las Profundidades" },
	},
})

Translate("esES", "shadowmage-vivian-lagrave", {
	title = "Maga de las sombras Vivian Lagrave",
	subtitle = "Erudita renegada de la F.E.K.",
