	aliases = { "Vivian Lagrave" },
	sections = {
		{
			title = "Resumen",
			text = [=[Vivian Lagrave es una maga de las sombras de los {link:forsaken}Renegados{/link} que sirve en la Fuerza Expedicionaria de {link:kargath}Kargath{/link}. Las {link:badlands}Tierras Inhóspitas{/link} le parecen desprovistas de encanto, y echa de menos las comodidades del {link:the-apothecarium}Apothecarium{/link}. Está en Kargath por una sola razón: los {link:dark-iron-dwarves}Hierro Negro{/link} saben cosas que la {link:royal-apothecary-society}Real Sociedad de Boticarios{/link} quiere saber, y ella piensa arrebatárselas.]=],
		},
		{
			title = "Importancia",
			text = [=[Vivian es la mano de {link:undercity}Entrañas{/link} en la guerra de la {link:horde}Horda{/link} contra los {link:dark-iron-dwarves}Hierro Negro{/link}. Estudia sus brebajes, su alquimia y el poder que mueve sus gólems, siempre para usos acordes con los fines de su pueblo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Busca la receta perdida de la cerveza Thunderbrew, robada por un {link:dark-iron-dwarves}Hierro Negro{/link}, para ver cómo podría volverse su fuerza contra los enanos de la {link:alliance}Alianza{/link}.
• Busca la Tablilla de Darkstone, obra de un alquimista muerto hace mucho, en la {red:blackrock-spire}Cumbre de Roca Negra{/red}.
• Envía a {link:undercity}Entrañas{/link} las esencias que dan poder a los gólems Hierro Negro.]=],
		},
	},
	mentions = {
		{ text = "Vivian Lagrave" },
		{ text = "La receta perdida de Thunderbrew" },
		{ text = "Vivian Lagrave y la Tablilla de Darkstone" },
		{ text = "La Tablilla de Darkstone" },
		{ text = "El último elemento" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Señor de la guerra Goretooth", note = "su comandante" },
	},
})

Translate("esES", "hierophant-theodora-mulvadania", {
	title = "Hierofante Theodora Mulvadania",
