Translate("esES", "thal-trak-proudtusk", {
	title = "Thal'trak Proudtusk",
	subtitle = "Soldado de la F.E.K.",
	found = "Kargath",
	hint = [=[Hable con el soldado de Kargath que espera noticias de su esposa.]=],
	allegiance = "Horda · Fuerza Expedicionaria de Kargath",
	aliases = { "Thal'trak" },
	sections = {
		{
			title = "Resumen",
			text = [=[Thal'trak Proudtusk es un soldado de la Fuerza Expedicionaria de {link:kargath}Kargath{/link}. Su esposa, Sha'ni, fue con un pelotón a {link:burning-steppes}Las Estepas Ardientes{/link} para averiguar qué hacían los ogros Firegut en sus rituales. De eso hace semanas. Nadie de su pelotón ha vuelto, y el señor de la guerra {link:warlord-goretooth}Goretooth{/link} le ha dicho a Thal'trak que pase página. Thal'trak no puede abandonar su puesto, y no puede pasar página.]=],
		},
		{
			title = "Importancia",
			text = [=[Thal'trak recuerda que la guerra en la montaña la pagan los soldados corrientes y quienes los esperan.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Envía a un buscador a averiguar qué fue de Sha'ni.
• Pide la argolla de nariz que ella llevaba, arrebatada por el {link:ogres}ogro{/link} {link:krom-grul}Krom'Grul{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Roca Machacamiedo",
			hint = [=[Averigüe el destino de la esposa de Thal'trak en Las Estepas Ardientes.]=],
			text = [=[Sha'ni no volvería a casa. Ella y Thal'trak habían planeado vivir con los padres de ella en las {link:the-hinterlands}Tierras del Interior{/link} cuando terminaran sus servicios. Lo único que volvió a {link:kargath}Kargath{/link} fue su argolla de nariz, recuperada del {link:ogres}ogro{/link} {link:krom-grul}Krom'Grul{/link} en las cuevas de la {link:dreadmaul-rock}Roca Machacamiedo{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:dreadmaul-rock}Roca Machacamiedo{/link}" },
		{ text = "{link:krom-grul}Krom'Grul{/link}" },
	},
	bonds = {
		{ id = "sha-ni-proudtusk", name = "Sha'ni Proudtusk", note = "su esposa" },
		{ id = "warlord-goretooth", name = "Señor de la guerra Goretooth", note = "su comandante" },
	},
})

Translate("esES", "neeka-bloodscar", {
	title = "Neeka Bloodscar",
	subtitle = "Exploradora jefe de Kargath",
	found = "Kargath",
	hint = "Hable con la exploradora jefe de Kargath.",
	allegiance = "Horda · Kargath",
	aliases = { "Neeka" },
	sections = {
		{
			title = "Resumen",
			text = [=[Neeka Bloodscar es la exploradora jefe de {link:kargath}Kargath{/link}. Las {link:badlands}Tierras Inhóspitas{/link} están cerca de las tierras de la {link:alliance}Alianza{/link} en {link:loch-modan}Loch Modan{/link}, y el camino entre Kargath y {link:stonard}Rocal{/link} es largo y peligroso. Sus corredores no siempre llegan. Juzga a los recién llegados por si son capaces de sobrevivir al calor y a las bestias de las Tierras Inhóspitas.]=],
		},
