			title = "Resumen",
			text = [=[Gorn es un {link:orcs}orco{/link} de {link:kargath}Kargath{/link} que recuerda con vergüenza la {link:second-war}Segunda Guerra{/link}. En esa guerra la {link:horde}Horda{/link} fue aliada de {link:deathwing}Alamuerte{/link}, y dos de los lugartenientes del dragón, {link:blacklash}Blacklash{/link} y {link:hematus}Hematus{/link}, siguen atados bajo el {link:lethlor-ravine}Barranco Lethlor{/link}. Gorn quiere silenciar a los depravados aliados de antaño de la Horda, para restaurar su honor.]=],
		},
		{
			title = "Importancia",
			text = [=[Gorn habla por el deseo de la nueva {link:horde}Horda{/link} de dejar atrás los crímenes de la antigua. También habla por sus duras lecciones sobre los {link:ogres}ogros{/link}, que ya no forman parte de la Horda.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Contrató a los ogros del jefe {link:boss-tho-grun}Tho'grun{/link} para hacerse con el Signo de la Tierra, y lo traicionaron.
• Envía a los luchadores de {link:kargath}Kargath{/link} a recuperar el Signo y romper el sello de {link:lethlor-ravine}Lethlor{/link}.]=],
		},
	},
	chapters = {
