			title = "Alianzas rotas",
			hint = [=[Ayude al orco de Kargath a dar muerte a los lugartenientes de Alamuerte.]=],
			text = [=[El Signo de la Tierra volvió a {link:kargath}Kargath{/link}, y los dracos de {link:lethlor-ravine}Lethlor{/link} fueron liberados solo para morir. Gorn lo vio como un paso más. El Vuelo Negro seguía del lado de los orcos renegados {link:blackrock-mountain}Roca Negra{/link}, y había que someter o eliminar a ambos. Con los dracos muertos, Kargath podía volver la mirada al oeste, hacia la {red:blackrock-spire}Cumbre de Roca Negra{/red}.]=],
		},
	},
	mentions = {
		{
			text = [=[Alianzas rotas, la traición de {link:boss-tho-grun}Tho'grun{/link}]=],
		},
		{ text = "Alianzas rotas, los dracos muertos" },
		{ text = "El Sello de la Tierra" },
	},
	bonds = {
		{ id = "boss-tho-grun", name = "Jefe Tho'grun", note = "lo traicionó" },
		{ id = "blacklash", name = "Blacklash", note = "un aliado de antaño al que silenciaría" },
		{ id = "hematus", name = "Hematus", note = "un aliado de antaño al que silenciaría" },
	},
})

